package service;

import domain.DailyLine;
import domain.Partner;
import domain.Transaction;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Builds per-partner daily settlement lines from the transaction feed. */
public class SettlementService {
    private final DataFiles data;
    private final RateService rates;
    private final BusinessDateResolver dates;

    public SettlementService(DataFiles data, RateService rates, BusinessDateResolver dates) {
        this.data = data;
        this.rates = rates;
        this.dates = dates;
    }

    public List<DailyLine> settle(LocalDate from, LocalDate to) {
        Map<String, long[]> acc = new TreeMap<>(); // key "date|partner" -> {count, grossKrw}
        for (Transaction t : data.transactions()) {
            LocalDate d = dates.dateOf(t.approvedAt());
            if (d.isBefore(from) || d.isAfter(to)) continue;
            Partner p = data.partner(t.partnerId()).orElse(null);
            if (p == null || !p.active()) continue;
            long krw = convert(t, d);
            long[] a = acc.computeIfAbsent(d + "|" + p.id(), k -> new long[2]);
            a[0]++;
            a[1] += krw;
        }
        List<DailyLine> out = new ArrayList<>();
        for (var e : acc.entrySet()) {
            String[] k = e.getKey().split("\\|");
            Partner p = data.partner(k[1]).orElseThrow();
            long gross = e.getValue()[1];
            out.add(new DailyLine(LocalDate.parse(k[0]), p.id(), (int) e.getValue()[0], gross,
                    Money.fee(gross, p.feeBps())));
        }
        return out;
    }

    private long convert(Transaction t, LocalDate businessDate) {
        var rate = rates.settlementRate(t.currency(), businessDate);
        return Money.toKrw(t.signedAmount(), rate, CurrencyPairs.unitOf(t.currency()));
    }
}
package service;

import domain.DailyLine;
import domain.StatementRow;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Compares our daily lines with the partners' statements. */
public class ReconcileService {

    /** Difference between our settlement and the partner's statement for a date/partner. */
    public record Mismatch(LocalDate date, String partnerId, String field, long ours, long theirs) {
        public long diff() { return ours - theirs; }
    }

    public List<Mismatch> compare(List<DailyLine> ours, List<StatementRow> theirs) {
        Map<String, DailyLine> mine = new HashMap<>();
        for (DailyLine l : ours) mine.put(key(l.date(), l.partnerId()), l);
        List<Mismatch> out = new ArrayList<>();
        for (StatementRow r : theirs) {
            DailyLine l = mine.remove(key(r.date(), r.partnerId()));
            if (l == null) {
                out.add(new Mismatch(r.date(), r.partnerId(), "missing", 0, r.grossKrw()));
                continue;
            }
            if (l.count() != r.count()) out.add(new Mismatch(r.date(), r.partnerId(), "count", l.count(), r.count()));
            if (l.grossKrw() != r.grossKrw()) out.add(new Mismatch(r.date(), r.partnerId(), "gross", l.grossKrw(), r.grossKrw()));
        }
        for (DailyLine l : mine.values()) {
            out.add(new Mismatch(l.date(), l.partnerId(), "unexpected", l.grossKrw(), 0));
        }
        out.sort((a, b) -> a.date().equals(b.date()) ? a.partnerId().compareTo(b.partnerId()) : a.date().compareTo(b.date()));
        return out;
    }

    private static String key(LocalDate d, String partner) {
        return d + "|" + partner;
    }
}
package api;

