                throw new IllegalStateException("no settlement rate for " + pair + " " + date + " (source "
                        + SETTLEMENT_SOURCE + " also fell back)");
            }
            return r;
        });
        return s.rate();
    }

    public int vendorCalls() {
        return vendorCalls;
    }
}
